// Delete soft-deletes the record addressed by its resource name: delete_time
// is set, the row stays. update_time is set to the same instant: the
// delete is the record's latest write, which a reader by update time can tell
// from any write after it.
func (r *GormTransientRfpRepository) Delete(ctx context.Context, name string) error {
	key, err := r.rowKey(name)
	if err != nil {
		return err
	}
	if h := r.Hooks.BeforeDelete; h != nil {
		if err := h(ctx, name); err != nil {
			return err
		}
	}
	res := r.markDeleted(ctx, r.DB, key)
	if res.Error != nil {
		return repox.MapGormErr(res.Error)
	}
	if res.RowsAffected == 0 {
		return repox.ErrNotFound
	}
	return nil
}

// markDeleted sets the soft-delete mark on the live row found by key
// (rowKey) through db: Delete's write, which a Batch runs inside its
// transaction.
func (r *GormTransientRfpRepository) markDeleted(ctx context.Context, db *gorm.DB, key string) *gorm.DB {
	now := time.Now()
	return db.WithContext(ctx).Model(&transientrfp.TransientRfp{}).
		Where("id = ? AND delete_time IS NULL", key).
		Updates(map[string]any{"delete_time": now, "update_time": now, "etag": repox.NewULID(), "expire_time": repox.ExpireAt(now, r.Retention)})
}

// Undelete clears the soft-delete mark and returns the restored record.
func (r *GormTransientRfpRepository) Undelete(ctx context.Context, name string) (*transient_rfpv1.TransientRfp, error) {
	key, err := r.rowKey(name)
	if err != nil {
		return nil, err
	}
	res := r.DB.WithContext(ctx).Model(&transientrfp.TransientRfp{}).
		Where("id = ? AND delete_time IS NOT NULL", key).
		Updates(map[string]any{"delete_time": nil, "etag": repox.NewULID(), "expire_time": nil})
	if res.Error != nil {
		return nil, repox.MapGormErr(res.Error)
	}
	if res.RowsAffected == 0 {
		if _, err := r.get(ctx, key); err != nil {
			return nil, err
		}
		return nil, fmt.Errorf("%w: %s is not deleted", repox.ErrAlreadyExists, name)
	}
	return r.get(ctx, key)
}

// Purge removes the record addressed by its resource name for good.
func (r *GormTransientRfpRepository) Purge(ctx context.Context, name string) error {
	key, err := r.rowKey(name)
	if err != nil {
		return err
	}
	if h := r.Hooks.BeforeDelete; h != nil {
		if err := h(ctx, name); err != nil {
			return err
		}
	}
	_, err = r.purge(ctx, r.DB, key, name, true)
	return repox.MapGormErr(err)
}

// purgeTx removes the row found by key (rowKey) inside tx, with the
// value-object rows it owns; gorm.ErrRecordNotFound when there is no such row.
func (r *GormTransientRfpRepository) purgeTx(ctx context.Context, tx *gorm.DB, key string) error {
	var existing transientrfp.TransientRfp
	if err := tx.WithContext(ctx).Preload("AccountSpecificInfo").Preload("HotelAddress").Preload("HotelAddress.Address").Preload("HotelAddress.Address.StreetNmbr").Preload("HotelAddress.Address.StateProv").Preload("HotelAddress.Address.CountryDisplayName").Preload("ContactInfoRoots", func(db *gorm.DB) *gorm.DB { return db.Order("id") }).Preload("ContactInfoRoots.CompanyDisplayName").First(&existing, "id = ?", key).Error; err != nil {
		return err
	}
	if err := transientrfp.NewTransientRfpStore(tx).DeleteByID(ctx, existing.ID); err != nil {
		return err
	}
	if existing.AccountSpecificInfoID != nil {
		if err := tx.WithContext(ctx).Delete(&transientrfp.AccountSpecificInfo{}, "id = ?", *existing.AccountSpecificInfoID).Error; err != nil {
			return err
		}
	}
	if d11 := existing.HotelAddress; d11 != nil {
		if err := tx.WithContext(ctx).Delete(&transientrfp.AddressPref{}, "id = ?", d11.ID).Error; err != nil {
			return err
		}
		if d12 := d11.Address; d12 != nil {
			if err := tx.WithContext(ctx).Delete(&transientrfp.AddressInfo{}, "id = ?", d12.ID).Error; err != nil {
				return err
			}
			if d13 := d12.StreetNmbr; d13 != nil {
				if err := tx.WithContext(ctx).Delete(&transientrfp.StreetNmbr{}, "id = ?", d13.ID).Error; err != nil {
					return err
				}
			}
			if d14 := d12.StateProv; d14 != nil {
				if err := tx.WithContext(ctx).Delete(&transientrfp.StateProv{}, "id = ?", d14.ID).Error; err != nil {
					return err
				}
			}
			if d15 := d12.CountryDisplayName; d15 != nil {
				if err := tx.WithContext(ctx).Delete(&transientrfp.CountryName{}, "id = ?", d15.ID).Error; err != nil {
					return err
				}
			}
		}
	}
	for i20 := range existing.ContactInfoRoots {
		d21 := &existing.ContactInfoRoots[i20]
		if err := tx.WithContext(ctx).Delete(&transientrfp.ContactInfoRoot{}, "id = ?", d21.ID).Error; err != nil {
			return err
		}
		if d22 := d21.CompanyDisplayName; d22 != nil {
			_ = d22
		}
	}
	return nil
}

// purge removes the row found by key (rowKey), named name, for good through
// db -- unless something
// still refers to it, when it keeps the row and reports kept: a row of this
// database holding a foreign key to it (asked first, then caught again from
// the constraint itself), or, when askReferrers, a referrer in another
// database or service (r.Refs). A purge never fails, and never cascades,
// because of a referrer. gorm.ErrRecordNotFound when there is no such row.
func (r *GormTransientRfpRepository) purge(ctx context.Context, db *gorm.DB, key, name string, askReferrers bool) (kept bool, err error) {
	if askReferrers && r.Refs.KeepOnPurge(ctx, "hotel.opentravel.org/TransientRfp", name) {
		return true, nil
	}
	// A savepoint inside a caller's transaction: a foreign key the query
	// above does not know (one from another generator run) rolls back only
	// this purge.
	err = db.WithContext(ctx).Transaction(func(tx *gorm.DB) error {
		return r.purgeTx(ctx, tx, key)
	})
	if repox.IsForeignKeyViolation(err) {
		r.Refs.Kept(ctx, name, "foreign key")
		return true, nil
	}
	return false, err
}

// PurgeExpired removes for good every deleted record whose expire_time is at
// or before now, keeping the ones something still refers to (see purge).
// Hooks do not run.
func (r *GormTransientRfpRepository) PurgeExpired(ctx context.Context, now time.Time) (repox.PurgeResult, error) {
	var res repox.PurgeResult
	in := repox.ListInput{
		PageSize:    500,
		ShowDeleted: true,
		ReadMask:    []string{"name"},
		Where: []filterx.Condition{
			{Field: "delete_time", Op: filterx.OpNull, Value: "false"},
			{Field: "expire_time", Op: filterx.OpLte, Value: now.UTC().Format(time.RFC3339Nano)},
		},
	}
	for {
		page, next, err := r.list(ctx, r.DB, in)
		if err != nil {
			return res, err
		}
		for _, m := range page {
			key, err := r.rowKey(m.GetName())
			if err != nil {
				return res, err
			}
			kept, err := r.purge(ctx, r.DB, key, m.GetName(), true)
			switch {
			case errors.Is(err, gorm.ErrRecordNotFound):
			case err != nil:
				return res, repox.MapGormErr(err)
			case kept:
				res.Kept = append(res.Kept, m.GetName())
			default:
				res.Purged = append(res.Purged, m.GetName())
			}
		}
		if next == "" {
			return res, nil
		}
		in.PageToken = next
	}
}

// ListByKeys reads every record whose filter field field is one of keys; see
// repox.ListByKeys.
func (r *GormTransientRfpRepository) ListByKeys(ctx context.Context, field string, keys []string, in repox.ListInput) ([]*transient_rfpv1.TransientRfp, error) {
	return repox.ListByKeys(ctx, field, keys, in, func(ctx context.Context, in repox.ListInput) ([]*transient_rfpv1.TransientRfp, string, error) {
		return r.List(ctx, in)
	})
}

// Compile-time proof the adapter satisfies the interface.
var _ TransientRfpRepository = (*GormTransientRfpRepository)(nil)

// gormBatch is Batch on GORM: queued writes run in the Unit's transaction on
// Commit.
type gormBatch struct {
	u         *repox.Unit
	db        *gorm.DB
	retention time.Duration
}

// Commit applies the Unit's writes; see repox.Unit.Commit.
func (b *gormBatch) Commit(ctx context.Context) error { return b.u.Commit(ctx) }

// CreateTransientRfp queues a create and returns the name the record will have.
func (b *gormBatch) CreateTransientRfp(in *transient_rfpv1.TransientRfp) (string, error) {
	r := &GormTransientRfpRepository{DB: b.db}
	m, named, err := r.newRow(in)
	if err != nil {
		return "", err
	}
	var locks []string
	if k, ok := any(m).(interface{ NoOverlapKeys() []string }); ok {
		locks = k.NoOverlapKeys()
	}
	queueTransientRfpReferences(b.u, named, nil)
	b.u.QueueGorm(locks, func(ctx context.Context, tx *gorm.DB) error {
		return r.insertTx(ctx, tx, named, m)
	})
	b.u.Record(repox.Change{Type: "hotel.opentravel.org/TransientRfp", Name: named.GetName(), Op: repox.ChangeCreate, Record: named})
	return named.GetName(), nil
}

// UpdateTransientRfp queues Update; in.Etag, when set, guards it, and a guard
// that fails rolls the whole batch back.
func (b *gormBatch) UpdateTransientRfp(in *transient_rfpv1.TransientRfp, paths []string) {
	r := &GormTransientRfpRepository{DB: b.db}
	key, err := r.rowKey(in.GetName())
	if err != nil {
		b.u.Fail(err)
		return
	}
	queueTransientRfpReferences(b.u, in, paths)
	b.u.QueueGorm(nil, func(ctx context.Context, tx *gorm.DB) error {
		return r.updateTx(ctx, tx, key, in, paths, nil)
	})
	b.u.Record(repox.Change{Type: "hotel.opentravel.org/TransientRfp", Name: in.GetName(), Op: repox.ChangeUpdate, Record: in, LoadPrior: repox.PriorOf(in.GetName(), getTransientRfp)})
}

